"""Typed CB28 result words and verified rule-bridge/counter/action listings."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xcb28,0xcb2c,'data','Puntatori IX/IY restituiti dall’ultima regola'),(0xcb2c,0xcb41,'code','Ponte regole: ripristino, chiamata e conservazione dei risultati'),(0xc9bf,0xca76,'code','Preflight, predicato, durata e corpo immediato o differito'),(0xa1c7,0xa24d,'code','Rilascio dei record: link finale e fusioni dei blocchi liberi')]
for a,b,body,end,label in[(0xe52f,0xe531,0xe531,0xe560,'Creazione del contatore privato'),(0xe57a,0xe57e,0xe57e,0xe588,'Decremento del contatore privato'),(0xe588,0xe58c,0xe58c,0xe5a8,'Cancellazione del contatore privato'),(0xe5a8,0xe5aa,0xe5aa,0xe5ad,'Attesa di un tick'),(0xde9d,0xdea4,0xdea4,0xdeaf,'OPEN ordinario: descrittore dell’oggetto restituito'),(0xdeaf,0xdeb6,0xdeb6,0xdec1,'CLOSE ordinario: descrittore dell’oggetto restituito'),(0xf198,0xf19a,0xf19a,0xf1a8,'Scelta probabilistica: conserva i puntatori della regola'),(0xf1d6,0xf1d8,0xf1d8,0xf1f6,'Test dell’ora: conserva i puntatori entranti'),(0xd769,0xd76d,0xd76d,0xd77e,'Polling del parser: rami di ritorno ancora non proiettati')]:
 regions.extend([(a,b,'data','Intestazione tipizzata · '+label),(body,end,'code',label)])
regions.append((0xe560,0xe57a,'code','Ricerca del contatore: puntatore al record o zero'))
notes={0xcb28:'Due word little-endian mutabili, non istruzioni. Primo risultato IX, secondo IY. La riscrittura ne possiede solo i callback ricostruiti; i percorsi ignoti revocano il campo, senza fallback al payload.',0xcb2c:'Il corpo riprende i risultati precedenti: non ricarica genericamente i due argomenti.',0xcb34:'Ingresso del predicato: il chiamante ha già selezionato IX e intestazione IY. Anche un predicato falso ritorna qui e salva i suoi risultati.',0xcb37:'Unico store del primo risultato. OPEN/CLOSE ordinari lasciano il descrittore caricato da A013; contatori e rilascio lasciano record o link specifici.',0xcb3b:'Unico store del secondo risultato. IY può essere un’intestazione, un predecessore o altro: non dedurlo sempre dal primo puntatore.',0xc9dd:'Il predicato esiste solo con bit6. I controlli di luce/classi precedenti possono fallire prima del ponte.',0xc9eb:'Predicato via CB34, poi ripristino dell’intestazione di selezione. CB28/CB2A conservano comunque ciò che il predicato ha restituito.',0xca40:'Il bit7 differisce il corpo: non si entra CB2C in questa visita.',0xca64:'Corpo immediato via CB2C: carica i risultati della chiamata precedente, non i puntatori A013/A015 per convenzione.',0xa1cf:'La ricerca parte dal link della testa libera 9FE3 e avanza in ordine.',0xa1fd:'Solo se la prima fusione fallisce, carica il valore del link come IX: è lo start del blocco liberato, non start+2. Non correggere la stranezza originale.',0xa206:'La seconda fusione mantiene IX; il suo risultato non sceglie un nuovo puntatore.',0xe531:'Alloca due byte di dati: il puntatore del nuovo contatore rimane in IX. A11C preserva IY.',0xe552:'La scelta casuale avviene prima dello store CB37. Durante il draw CB28 conserva il risultato precedente, non il record appena allocato.',0xe560:'A0F7 attraversa la lista: alla fine IX è il record trovato o zero. IY dell’intestazione rimane intatto.',0xe573:'Un predicato senza contatore fallisce ma salva comunque IX=0 e IY=intestazione.',0xe57e:'Se il decremento non arriva a zero, conserva il record. A zero passa al rilascio E58C e restituisce il suo link, anche se il risultato logico è fallimento.',0xe58f:'A104 cerca il predecessore della lista dei contatori. Primo elemento: IY=9FE7; altrimenti IY=record precedente.',0xe5a2:'A1C7 lascia in IX il link libero derivato dalle fusioni. È diverso dall’IY predecessore della lista dei contatori.',0xdea4:'LD IX,(A013) possiede esplicitamente il descrittore dell’oggetto. Il modello lo deriva dall’ID risolto solo dopo il corpo ordinario riuscito.',0xdeb6:'Anche CLOSE ricarica A013. Non bisogna conservarvi il puntatore di un precedente contatore.',0xf19a:'D29D conserva IX/IY sullo stack; la regola restituisce quindi i risultati entranti. Nessun nuovo valore viene inventato dalla percentuale.',0xf1d8:'Il confronto usa A/B/HL e non modifica IX/IY, anche nei ritorni di fallimento DC15.',0xd770:'Il polling del parser può riscrivere CB28 dopo l’ultimo NPC. Questa analisi non completa tutti i suoi rami: tornando al prompt si revoca il campo.'}
fields=[['CB28–CB29','Risultato IX','Descrittore, contatore o link restituito; solo callback compresi posseduti'],['CB2A–CB2B','Risultato IY','Intestazione o predecessore; può essere sconosciuto anche con IX noto'],['Writer','CB37 / CB3B','Store anche dopo predicato falso; corpo differito non esegue CB2C'],['LOAD','Proprietà esplicita','Assente resta sconosciuto; non installare zero o il valore di una cattura']]
lines=['; Analisi offline: dati tipizzati separati dal codice; byte riasssemblati contro il payload.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/rule-registers';(root/'rule-results.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=146,**({'fields':fields}if a==0xcb28 else{}))for a,b,k,l in regions]),indent=2,ensure_ascii=False)+'\n');print(count,total)
